.version 7.0
.target sm_80
.address_size 64

.visible .entry scan_kernel(
    .param .u64 input_ptr,
    .param .u64 output_ptr,
    .param .u32 rows,
    .param .u32 cols
)
{
    // ------------------------------
    // Registers
    // ------------------------------
    .reg .pred %p, %p0, %p1;
    .reg .u32 %tid, %bid, %i, %j;
    .reg .u64 %in_ptr, %out_ptr, %in_row_ptr, %out_row_ptr;
    .reg .u64 %row_offset, %thread_offset;
    .reg .u64 %tmp64;
    .reg .u16 %tmp16;
    .reg .f16 %val_f16, %out_f16;
    .reg .f32 %val_f32, %sum, %prefix, %running, %accum, %temp;
    .reg .u32 %cols32, %rows32;

    // ------------------------------
    // Load kernel parameters
    // ------------------------------
    ld.param.u64 %input_ptr, [input_ptr];
    ld.param.u64 %output_ptr, [output_ptr];
    ld.param.u32 %rows32, [rows];
    ld.param.u32 %cols32, [cols];

    // ------------------------------
    // Thread / block indices
    // ------------------------------
    mov.u32 %tid, %tid.x;
    mov.u32 %bid, %ctaid.x;

    // ------------------------------
    // Compute start address of this row (in bytes)
    // row_offset = bid * cols * sizeof(__half)  (sizeof half = 2)
    // ------------------------------
    mul.wide.u32 %row_offset, %bid, %cols32;   // elements
    shl.b64 %row_offset, %row_offset, 1;      // bytes

    // Base pointers for this row
    add.u64 %in_row_ptr, %input_ptr, %row_offset;
    add.u64 %out_row_ptr, %output_ptr, %row_offset;

    // ------------------------------
    // Constants: elements per thread (EPT) = 128, blockDim = 256
    // ------------------------------
    // (hard‑coded in the code below)

    // ------------------------------
    // Compute per‑thread start offset (bytes)
    // thread_offset = tid * (EPT * sizeof(half)) = tid * 256
    // ------------------------------
    shl.b64 %thread_offset, %tid, 8;   // 2^8 = 256

    // -------------------------------------------------
    // First pass: compute per‑thread total (sum of its 128 elements)
    // -------------------------------------------------
    add.u64 %in_ptr, %in_row_ptr, %thread_offset;
    mov.f32 %sum, 0f0;
    mov.u32 %i, 0;

LOOP_SUM:
    ld.global.u16 %tmp16, [%in_ptr];
    cvt.f16.u16 %val_f16, %tmp16;
    cvt.f32.f16 %val_f32, %val_f16;
    fadd.f32 %sum, %sum, %val_f32;

    add.u64 %in_ptr, %in_ptr, 2;
    add.u32 %i, %i, 1;
    setp.lt.u32 %p, %i, 128;
    @%p bra LOOP_SUM;

    // -------------------------------------------------
    // Store per‑thread totals into shared memory (fp32)
    // -------------------------------------------------
    .shared .align 4 .b8 smem[256*4];
    mul.wide.u32 %tmp64, %tid, 4;
    st.shared.f32 [smem+%tmp64], %sum;

