    // Barrier before prefix computation
    // -------------------------------------------------
    bar.sync 0;

    // -------------------------------------------------
    // Thread 0 computes exclusive prefix of per‑thread totals
    // -------------------------------------------------
    setp.eq.u32 %p0, %tid, 0;
    @%p0 {
        mov.f32 %accum, 0f0;
        mov.u32 %j, 0;
PREFIX_LOOP:
        mul.wide.u32 %tmp64, %j, 4;
        ld.shared.f32 %temp, [smem+%tmp64];
        st.shared.f32 [smem+%tmp64], %accum;
        fadd.f32 %accum, %accum, %temp;

        add.u32 %j, %j, 1;
        setp.lt.u32 %p1, %j, 256;
        @%p1 bra PREFIX_LOOP;
    }

    // -------------------------------------------------
    // Barrier after prefix computation
    // -------------------------------------------------
    bar.sync 0;

    // -------------------------------------------------
    // Load this thread's prefix (sum of all previous threads)
    // -------------------------------------------------
    mul.wide.u32 %tmp64, %tid, 4;
    ld.shared.f32 %prefix, [smem+%tmp64];

