    // Second pass: write inclusive scan results
    // -------------------------------------------------
    add.u64 %in_ptr, %in_row_ptr, %thread_offset;
    add.u64 %out_ptr, %out_row_ptr, %thread_offset;
    mov.f32 %running, %prefix;
    mov.u32 %i, 0;

LOOP_WRITE:
    ld.global.u16 %tmp16, [%in_ptr];
    cvt.f16.u16 %val_f16, %tmp16;
    cvt.f32.f16 %val_f32, %val_f16;
    fadd.f32 %running, %running, %val_f32;

    cvt.f16.f32 %out_f16, %running;
    cvt.u16.f16 %tmp16, %out_f16;
    st.global.u16 [%out_ptr], %tmp16;

